def rename(path, mapping):
    data = json.load(open(path))
    count = 0
    def walk(obj):
        nonlocal count
        if isinstance(obj, dict):
            for k in list(obj):
                if k in mapping and isinstance(obj[k], str):
                    obj[k] = mapping[k]
                    count += 1
                walk(obj[k])
        elif isinstance(obj, list):
            for v in obj:
                walk(v)
    walk(data)
    with open(path, "w") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
